-- A settled transcript plus a tool part that is still running. Apply after schema.sql.

-- The native fork copies settled rows through the inclusive boundary, with new IDs.
SELECT 'msg_fixture_fork_' || seq, 'ses_fixture_fork', type, seq, time_created, time_updated, data
FROM session_message WHERE session_id = 'ses_fixture' AND seq <= 10;
SELECT 'msg_fixture_fork_' || m.seq, 'ses_fixture_fork', p.ordinal, p.type, p.call_id, p.time_created, p.time_updated, p.data
FROM session_part p JOIN session_message m ON p.message_id = m.id
WHERE p.session_id = 'ses_fixture' AND m.seq <= 10;
SELECT 'ses_fixture_fork', 'msg_fixture_fork_' || seq, hash, seq
FROM blob_ref WHERE session_id = 'ses_fixture' AND seq <= 10;

-- Delegation starts a fresh child transcript and uses a different relationship.
VALUES ('ses_fixture_worker', 'fixture-project', 'ses_fixture', 'fixture-worker', '/fixture/project', 'Fixture worker', '2.2.5', 1794078000025, 1794078000025);
VALUES ('msg_worker_task', 'ses_fixture_worker', 'user', 1, 1794078000025, 1794078000025,
        '{"text":"Fixture worker task.","time":{"created":1794078000025}}');
